<template><div class="page-screen" :data-kind="kind"><nav v-if="breadcrumbs.length" class="breadcrumb" aria-label="当前位置"><button @click="root">{{space?'协作空间':kind==='shared'?'共享文件':'我的文件'}}</button><template v-for="c in breadcrumbs" :key="c.id"><Icon name="right"/><button @click="enterCrumb(c)">{{c.name}}</button></template></nav><header class="page-head"><div><div class="page-title-line"><h1 class="page-title">{{title}}</h1><span v-if="kind==='my-files'||space" class="page-scope"><Icon :name="space?'building':'lock'"/>{{space?'团队协作':'个人空间'}}</span></div><p class="page-subtitle">{{subtitle}}</p></div><div class="head-actions"><template v-if="space"><button class="btn" @click="run(()=>ops.members(space))"><Icon name="people"/>成员</button><button class="icon-button" aria-label="空间操作" @click="spaceMenu"><Icon name="more"/></button></template><template v-if="canWrite"><button class="btn" @click="run(()=>ops.createFolder())"><Icon name="folder"/>新建文件夹</button><button class="btn primary" @click="$emit('upload')"><Icon name="upload"/>上传文件</button></template><button v-if="kind==='trash'&&!route.query.workspaceId" class="btn danger" @click="run(ops.clearTrash)"><Icon name="trash"/>清空回收站</button></div></header>
<div v-if="kind==='shared'" class="segmented"><button :class="{active:!outgoing}" @click="patch({tab:'incoming',parentId:'',shareId:'',page:1})">共享给我的</button><button :class="{active:outgoing}" @click="patch({tab:'outgoing',parentId:'',shareId:'',page:1})">我共享的</button></div>
<div v-if="kind==='search'" class="search-filters"><select class="input" :value="route.query.scope||'all'" @change="patch({scope:$event.target.value,page:1})"><option value="all">全部位置</option><option value="personal">我的文件</option><option value="shared">收到的共享</option><option value="workspace">协作空间</option></select><select class="input" :value="route.query.itemType||'all'" @change="patch({itemType:$event.target.value,page:1})"><option value="all">全部类别</option><option value="file">文件</option><option value="folder">文件夹</option><option value="workspace">协作空间</option></select><select class="input" :value="route.query.owner||''" @change="patch({owner:$event.target.value,page:1})"><option value="">全部所有者</option><option v-for="o in owners" :key="o.id" :value="o.id">{{o.name}}</option></select><label>从<input class="input" type="date" :value="route.query.from||''" @change="patch({from:$event.target.value,page:1})"/></label><label>至<input class="input" type="date" :value="route.query.to||''" @change="patch({to:$event.target.value,page:1})"/></label><select class="input" :value="sortBy" @change="sort($event.target.value)"><option value="relevance">相关程度</option><option value="name">名称</option><option value="updatedAt">修改时间</option></select></div>
<div class="table-page-body"><div v-if="selected.size" class="selectionbar"><span class="selection-count">已选择 <b>{{selected.size}}</b> 项</span><template v-if="kind==='trash'"><button class="btn ghost" @click="run(()=>ops.restore(selectedItems))"><Icon name="restore"/>恢复</button><button class="btn ghost selection-danger" @click="run(()=>ops.purge(selectedItems))"><Icon name="trash"/>永久删除</button></template><template v-else-if="outgoing"><button class="btn ghost" @click="revokeSelected">撤销共享</button></template><template v-else><button v-if="allManage" class="btn ghost" @click="run(()=>ops.share(selectedItems))"><Icon name="shared"/>共享</button><button v-if="allDownload" class="btn ghost" @click="run(()=>ops.download(selectedItems))"><Icon name="download"/>下载</button><button v-if="allCopy" class="btn ghost" @click="run(()=>ops.copyOrMove(selectedItems))"><Icon name="copy"/>复制到</button><button v-if="allManage" class="btn ghost" @click="run(()=>ops.copyOrMove(selectedItems,false))"><Icon name="move"/>移动</button><button v-if="allManage" class="btn ghost" @click="run(()=>ops.rename(selectedItems))">重命名</button><button v-if="allManage" class="btn ghost selection-danger" @click="run(()=>ops.remove(selectedItems))"><Icon name="trash"/>删除</button></template><button class="cancel-selection" @click="selected=new Set()"><Icon name="close"/>取消选择</button></div>
<div v-else class="toolbar"><div class="filter-tabs"><button v-for="f in filters" :key="f[0]" class="filter-tab" :class="{active:filter===f[0]}" @click="patch({fileType:f[0],page:1})">{{f[1]}}<span v-if="f[0]==='all'">{{total}}</span></button></div><div class="toolbar-right"><input v-if="!['home','search'].includes(kind)" class="input directory-search" type="search" :value="route.query.keyword||''" placeholder="筛选当前列表" @input="filterKeyword"/><button class="icon-button view-pref" title="界面偏好" @click="run(()=>ops.preferences(router))"><Icon name="sliders"/></button><div v-if="kind!=='trash'&&!outgoing" class="view-switch"><button class="icon-button" :class="{on:ui.prefs.layout==='list'}" title="列表" @click="layout('list')"><Icon name="list"/></button><button class="icon-button" :class="{on:ui.prefs.layout==='grid'}" title="网格" @click="layout('grid')"><Icon name="grid"/></button></div></div></div>
<div class="table-shell"><div class="table-scroll" ref="scroll" tabindex="0">
<div v-if="kind==='home'" class="home-content"><div class="section-heading"><h2>继续上次的工作</h2><RouterLink class="text-button" to="/recent">查看全部<Icon name="right"/></RouterLink></div><div class="home-continue"><article class="continue-card" v-for="item in recent" :key="item.id"><button class="grid-preview" @click="open(item)"><div class="preview-generic"><FileGlyph :item="item" size="large"/></div></button><div class="grid-caption"><FileGlyph :item="item"/><button class="file-name-button truncate" @click="open(item)"><NameText :item="item"/><span class="file-secondary">{{item.displayPath}}</span></button></div></article></div><p v-if="!recent.length&&!busy" class="form-note">打开文件后，可在这里继续上次的工作。</p><section class="folder-section" v-if="quickFolders.length"><div class="section-heading"><h2>快速访问</h2><RouterLink class="text-button" to="/favorites">查看收藏<Icon name="right"/></RouterLink></div><div class="folder-strip"><button v-for="item in quickFolders" :key="item.id" class="folder-card" @click="open(item)"><span class="folder-top"><FileGlyph :item="item" size="large"/></span><span class="folder-title">{{item.name}}</span><span class="folder-meta">{{item.favorite?'已收藏':'个人文件夹'}}</span></button></div></section><div class="section-heading"><h2>最近更新</h2><span class="small-text muted">你可以访问的文件</span></div></div>
<div v-if="error" class="empty"><Icon name="info"/><h3>加载失败</h3><p>{{error}}</p><button class="btn" @click="load">重试</button></div><div v-else-if="busy&&!items.length" class="empty"><p>正在加载…</p></div><FileCollection v-else :items="items" :selected="selected" :grid="ui.prefs.layout==='grid'&&kind!=='home'" :trash="kind==='trash'" :outgoing="outgoing" :search="kind==='search'" :show-location="!['my-files','workspace'].includes(kind)" :keyword="route.query.keyword||''" :sort-by="sortBy" :sort-order="sortOrder" @select="select" @all="selectAll" @sort="sort" @open="open" @menu="fileMenu"><template #empty><div class="empty"><div class="empty-symbol"><Icon name="folder"/></div><h3>{{kind==='search'&&!route.query.keyword?'输入关键词开始搜索':'没有匹配的项目'}}</h3><p>{{kind==='search'?'按文件、文件夹或空间名称搜索。':'调整筛选条件，或在当前目录添加文件。'}}</p></div></template></FileCollection></div><Pager :total="total" :page="page" :size="pageSize" :busy="busy" @page="patch({page:$event})" @size="changeSize"/></div></div></div></template>
<script setup>
import { directoryBreadcrumbs, breadcrumbLocation } from '../navigation';
import {ref,computed,watch,onUnmounted} from 'vue';import {useRoute,useRouter,RouterLink} from 'vue-router';import Icon from '../components/Icon.vue';import FileGlyph from '../components/FileGlyph.vue';import NameText from '../components/NameText.vue';import FileCollection from '../components/FileCollection.vue';import Pager from '../components/Pager.vue';import * as api from '../api';import * as ops from '../operations';import {ui,run,changed,confirm} from '../state';import {searchDateBoundary} from '../../composables/drive/searchResults';
defineEmits(['upload']);const route=useRoute(),router=useRouter(),items=ref([]),total=ref(0),busy=ref(false),error=ref(''),selected=ref(new Set()),space=ref(null),crumbs=ref([]),recent=ref([]),quickFolders=ref([]),owners=ref([]),sortBy=ref('updatedAt'),sortOrder=ref('desc'),scroll=ref(null);let controller,seq=0,timer,previousContext='';
const breadcrumbs=computed(()=>directoryBreadcrumbs(crumbs.value,space.value));
const kind=computed(()=>route.params.id?'workspace':route.path==='/'?'home':route.path.slice(1)),outgoing=computed(()=>kind.value==='shared'&&route.query.tab==='outgoing');
const context=computed(()=>({'my-files':'my-files','workspace':'workspace-directory','trash':'trash','shared':outgoing.value?'shared-outgoing':'shared-incoming'})[kind.value]||'');
const page=computed(()=>Number(route.query.page)||1),pageSize=computed(()=>Number(route.query.size)||Number(ui.prefs.pageSize)||50),filter=computed(()=>route.query.fileType||'all');
const title=computed(()=>space.value?.name||({'home':'首页','my-files':'我的文件','shared':'共享文件','trash':'回收站','recent':'最近打开','favorites':'我的收藏','search':'搜索结果'})[kind.value]);
const subtitle=computed(()=>kind.value==='home'?(ui.session?.personName||'')+'，欢迎回来。继续处理最近的工作文件。':kind.value==='search'?'在所有有权限的内容中按名称查找。':kind.value==='trash'?'已删除的文件可以恢复，永久删除需要确认。':'集中维护工作资料，让文件清晰有序。');
const canWrite=computed(()=>['home','my-files'].includes(kind.value)||(kind.value==='workspace'&&space.value?.status==='ACTIVE'&&['OWNER','ADMIN','MEMBER'].includes(space.value?.myRole)));
const filters=computed(()=>['trash','recent','favorites','home'].includes(kind.value)||outgoing.value?[['all','全部']]:kind.value==='search'?[['all','全部'],['word','文档'],['excel','表格'],['pdf','PDF'],['image','图片'],['other','其他']]:[['all','全部'],['doc','文档'],['excel','表格'],['image','图片与设计'],['other','其他']]);
const selectedItems=computed(()=>items.value.filter(i=>selected.value.has(i.rowKey||i.id))),allManage=computed(()=>selectedItems.value.length&&selectedItems.value.every(i=>i.allowManage)),allCopy=computed(()=>selectedItems.value.length&&selectedItems.value.every(i=>i.allowCopy)),allDownload=computed(()=>selectedItems.value.length&&selectedItems.value.every(i=>i.allowDownload||i.itemType==='folder'&&i.allowCopy));
function patch(values){const q={...route.query,...values};for(const k of Object.keys(q))if(q[k]===''||q[k]==null)delete q[k];return router.push({path:route.path,query:q});}
function filterKeyword(e){clearTimeout(timer);const keyword=e.target.value;timer=setTimeout(()=>patch({keyword,page:1}),300);}
function select(id){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next;}
function selectAll(){selected.value=items.value.every(i=>selected.value.has(i.rowKey||i.id))?new Set():new Set(items.value.map(i=>i.rowKey||i.id));}
async function sort(field){const order=sortBy.value===field&&sortOrder.value==='asc'?'desc':'asc';if(context.value){try{await api.updateDriveSortPreference({context:context.value,sortBy:field,sortOrder:order});}catch(e){error.value=e.message;return;}}await patch({sortBy:field,sortOrder:order,page:1});}
async function changeSize(size){await run(()=>api.send('/api/drive/preferences/ui',{pageSize:size},'PUT'));ui.prefs.pageSize=size;await patch({size,page:1});}
async function layout(value){ui.prefs.layout=value;await run(()=>api.send('/api/drive/preferences/ui',{layout:value},'PUT'));}
function root(){router.push(space.value?'/workspaces':kind.value==='shared'?'/shared':'/my-files');}
function enterCrumb(c){return router.push(breadcrumbLocation(route,c));}
function open(item){if(busy.value)return;run(()=>ops.openItem(item,router));}
function fileMenu(event,item){let actions=ops.fileActions(item,router);if(outgoing.value)actions=[{label:'查看文件',icon:'file',run:()=>ops.openItem(item,router)},{label:'修改共享',icon:'edit',run:()=>ops.editShare(item.shareRecord)},{label:'撤销共享',icon:'close',run:async()=>{if(await confirm('撤销共享？','停止此对象的共享权限。')){await api.revokeDriveShare(item.rowKey);changed();}}}];ops.menu(event,actions);}
function spaceMenu(e){ops.menu(e,[{label:'空间动态',icon:'info',run:async()=>{const rows=await api.get('/api/workspaces/'+space.value.id+'/activities');void (await import('../state')).dialog({title:'空间动态',records:rows.map(r=>({id:r.id,name:r.name,description:r.action+' · '+r.createdAt}))});}},{label:'重命名空间',icon:'edit',disabled:!['OWNER','ADMIN'].includes(space.value.myRole),run:()=>ops.renameSpace(space.value)},{label:'空间回收站',icon:'trash',disabled:!canWrite.value,run:()=>router.push({path:'/trash',query:{workspaceId:space.value.id}})},{label:'归档空间',icon:'trash',disabled:space.value.myRole!=='OWNER',run:()=>ops.archiveSpace(space.value,router)}]);}
async function revokeSelected(){if(await confirm('撤销选中共享？','选中对象将失去相应权限。')){const r=await api.revokeDriveShares({itemIds:selectedItems.value.map(i=>i.rowKey)});(await import('../state')).batchResult(r);}}
async function load(){
 const n=++seq;controller?.abort();controller=new AbortController();const signal=controller.signal;busy.value=true;error.value='';selected.value=new Set();ui.detail=null;
 try{
  if(context.value&&context.value!==previousContext){const pref=await api.getDriveSortPreference(context.value);if(n!==seq)return;sortBy.value=pref.sortBy;sortOrder.value=pref.sortOrder;previousContext=context.value;}
  if(!context.value)previousContext='';
  sortBy.value=String(route.query.sortBy||(!context.value?(kind.value==='search'?'relevance':kind.value==='recent'?'lastAccessedAt':'updatedAt'):sortBy.value));sortOrder.value=String(route.query.sortOrder||sortOrder.value);
  const q={...route.query,page:page.value,size:pageSize.value,sortBy:sortBy.value,sortOrder:sortOrder.value};if(q.fileType==='all')delete q.fileType;
  let result;
  if(kind.value==='workspace'){space.value=await api.getWorkspace(route.params.id);if(n!==seq)return;}else space.value=null;
  ui.context={scopeType:space.value?'WORKSPACE':'PERSONAL',scopeId:space.value?.id||'',scopeName:space.value?.name||'我的文件',parentId:(space.value||kind.value==='my-files')?(route.query.parentId||''):'',readOnly:Boolean(space.value&&!canWrite.value)};
  if(kind.value==='home')result=await api.get('/api/drive/me/home',q,signal);
  else if(['recent','favorites'].includes(kind.value))result=await api.get('/api/drive/me/'+(kind.value==='recent'?'recent-opened/query':'favorites'),q,signal);
  else if(kind.value==='search'){
   if(!String(q.keyword||'').trim())result={items:[],total:0};else result=await api.searchAllItems({...q,updatedFrom:searchDateBoundary(q.from),updatedTo:searchDateBoundary(q.to,true)}, {signal});
  } else if(kind.value==='trash')result=route.query.workspaceId?await api.get('/api/workspaces/'+route.query.workspaceId+'/trash/items/query',q,signal):await api.get('/api/drive/trash/items/query',q,signal);
  else if(outgoing.value)result=await api.get('/api/drive/shares/outgoing',q,signal);
  else result=await api.get('/api/drive/me/browse',{...q,source:space.value?'workspace':kind.value==='shared'?'shared':'personal',workspaceId:space.value?.id||''},signal);
  if(n!==seq)return;
  let list=result.items||[];
  if(outgoing.value){const presentation=await api.present(list.filter(r=>r.item).map(r=>r.item.id));const byId=new Map(presentation.map(i=>[i.id,i]));list=list.filter(r=>r.item).map(r=>({...r.item,...byId.get(r.item.id),rowKey:r.id,targetName:r.targetName,permission:r.permission,shareRecord:r}));}
  if(kind.value==='trash')list=list.map(r=>({...r,deleted:true,allowManage:true,source:route.query.workspaceId?'workspace':'personal'}));
  if(n!==seq)return;items.value=list;total.value=result.total||0;recent.value=result.recent||[];quickFolders.value=result.quickFolders||[];owners.value=result.owners||[];crumbs.value=[];
  if(route.query.parentId){try{const path=kind.value==='shared'?await api.getIncomingDriveSharePath(route.query.shareId,route.query.parentId):await api.getDrivePath(route.query.parentId);if(n===seq)crumbs.value=path||[];}catch(e){if(n===seq)error.value=e.message;}}
  if(n===seq&&result.page&&result.page!==page.value)await patch({page:result.page});
 }catch(e){if(n===seq&&e.name!=='AbortError'){error.value=e.message;items.value=[];}}finally{if(n===seq)busy.value=false;}
}
watch(()=>route.fullPath,()=>{clearTimeout(timer);if(scroll.value)scroll.value.scrollTop=0;void load();},{immediate:true});watch(()=>ui.revision,load);onUnmounted(()=>{seq++;controller?.abort();clearTimeout(timer);});
</script>
